from common import *
import re, sys

bench("/__test/reset", {})
def errs_of(pg, scope="main"):
    return pg.evaluate("(s) => [...document.querySelectorAll(s + ' .field.err .errmsg')].map(e => e.textContent.trim()).filter(x => x)", scope)
def box(pg, id_):
    return pg.evaluate("(i) => { const b = document.getElementById(i); return b && b.classList.contains('on') ? b.innerText.trim() : '' }", id_)

