    print("=== E. SIMULATEUR DE PRIX (montants) ===")
    pg.goto(B + "/offre"); pg.wait_for_timeout(500)
    def sim(fm, n):
        pg.evaluate("(f) => { const r = document.querySelector('input[name=fm][value=' + f + ']'); r.checked = true; r.dispatchEvent(new Event('change', {bubbles: true})); r.dispatchEvent(new Event('input', {bubbles: true})); }", fm)
        pg.evaluate("(n) => { const r = document.getElementById('mails'); r.value = n; r.dispatchEvent(new Event('input', {bubbles: true})); r.dispatchEvent(new Event('change', {bubbles: true})); }", n)
        pg.wait_for_timeout(80); return int(re.sub(r"\D", "", pg.inner_text("#c-m")))
